import ast
from pathlib import Path
root=Path('scripts')
mods={p.stem:p for p in root.glob('*.py')}
seen=set(); stack=['omega_voice_world_patch']
while stack:
    m=stack.pop()
    if m in seen or m not in mods: continue
    seen.add(m)
    tree=ast.parse(mods[m].read_text(encoding='utf-8'))
    for n in ast.walk(tree):
        if isinstance(n,ast.Import):
            for a in n.names:
                k=a.name.split('.')[0]
                if k in mods and k not in seen: stack.append(k)
        elif isinstance(n,ast.ImportFrom) and n.level==0 and n.module:
            k=n.module.split('.')[0]
            if k in mods and k not in seen: stack.append(k)
print('===CLOSURE===')
